#include <condition_variable>
#include <iostream>
#include <mutex>
#include <queue>
#include <thread>

int main() {
    long long n = 0;
    std::cin >> n;

    std::mutex mtx;
    std::condition_variable cv;
    std::queue<long long> q;
    bool finished = false;
    long long sum = 0;

    std::thread producer([&] {
        for (long long i = 1; i <= n; ++i) {
            {
                std::lock_guard<std::mutex> lock(mtx);
                q.push(i);
            }
            cv.notify_one();
        }
        {
            std::lock_guard<std::mutex> lock(mtx);
            finished = true;
        }
        cv.notify_one();
    });

    std::thread consumer([&] {
        for (;;) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [&] { return !q.empty() || finished; });
            if (q.empty()) {
                break;
            }
            long long value = q.front();
            q.pop();
            lock.unlock();
            sum += value;
        }
    });

    producer.join();
    consumer.join();

    std::cout << sum << '\n';
    return 0;
}
